void mobi_buffer_move(MOBIBuffer *buf, int offset, size_t size) { size_t tomove = offset < 0 ? -offset : offset; char *src = (char *)(buf->data + buf->offset); if (offset >= 0) { if (buf->offset + tomove + size > buf->size) { buf->error = 9; return ; } src += tomove; } else { if (buf->offset < tomove) { buf->error = 9; return ; } src -= tomove; } memmove(buf->data + buf->offset, src, size); buf->offset += size; }